      <div class="filters" role="group" :aria-label="copy.filterLabel"><button v-for="filter in filters" :key="filter.value" :class="{active:activeFilter===filter.value}" @click="activeFilter=filter.value">{{filter.label}}</button></div>
      <div v-if="loading" class="grid"><article v-for="n in 8" :key="n" class="card skeleton-card"><div></div><i></i><i></i></article></div>
      <p v-else-if="error" class="status">{{copy.error}}</p><p v-else-if="!villas.length" class="status">{{copy.empty}}</p>
      <div v-else class="grid"><article v-for="(villa,index) in filteredVillas" :key="villa.slug" class="card"><div class="media"><DynamicVillaImage :images="villa.imageUrls || [villa.coverUrl]" :alt="villa.name" :offset="index * 1500"/><span class="badge">{{localBadge(villa)}}</span><strong>{{copy.discover}}</strong></div><div class="body"><small><MapPin/>{{villa.destination}}</small><h3>{{villa.name}}</h3><span class="collection">{{localBadge(villa)}}</span><ul class="features"><li v-for="feature in villa.features" :key="feature"><Check/>{{localFeature(feature)}}</li></ul><RouterLink :to="detail(villa.slug)" class="link">{{copy.viewVilla}} <ArrowRight/></RouterLink></div></article></div>
    </section>

    <section class="experience"><div class="shell experience-layout"><header class="experience-head"><span class="kicker">{{copy.skyExperience}}</span><h2 v-html="copy.experienceTitle"></h2><p>{{copy.experienceText}}</p><a href="#villas" class="experience-cta">{{copy.discoverExperience}} <ArrowRight/></a></header><div class="experience-showcase"><div class="experience-cards"><article v-for="item in experiences" :key="item.key"><img :src="item.image" :alt="copy.experienceItems[item.key]" :class="{'experience-card__image--flight':item.key==='flight'}" loading="lazy"><div><span><component :is="item.icon"/>{{copy.experienceItems[item.key]}}</span><p>{{copy.experienceDescriptions[item.key]}}</p></div></article></div><div class="service-row"><article v-for="item in complementaryServices" :key="item.key"><component :is="item.icon"/><div><strong>{{copy.serviceItems[item.key].title}}</strong><span>{{copy.serviceItems[item.key].text}}</span></div></article></div></div></div></section>

