const refreshVillas=async()=>{try{villas.value=await getVillas();error.value=false}catch(e){console.error('Unable to load villas',e);error.value=true}finally{loading.value=false}};
let unsubscribe=()=>{};
onMounted(async()=>{await refreshVillas();unsubscribe=subscribeToVillas(refreshVillas)});
onBeforeUnmount(()=>unsubscribe());
